"""
Action Executor Module.

Responsible for safely executing functions with arguments identified by the agents,
providing validation, safety checks, execution feedback, and error handling.
"""

from __future__ import annotations

import inspect
import logging
from typing import Any, Callable

import tools.tools as system_tools

log = logging.getLogger("action_executor")


class ActionExecutionError(Exception):
    """Raised when action execution fails."""
    pass


class ActionExecutor:
    """Executes functions and arguments generated by the Two-Agent system."""

    def __init__(self, dry_run: bool = False):
        self.dry_run = dry_run
        self._available_tools: dict[str, Callable] = self._discover_tools()

    def _discover_tools(self) -> dict[str, Callable]:
        """Discover callable actions exported in tools.tools."""
        discovered = {}
        for name in dir(system_tools):
            if name.startswith("_"):
                continue
            obj = getattr(system_tools, name)
            if callable(obj) and not isinstance(obj, type):
                discovered[name] = obj
        return discovered

    def is_executable(self, func_name: str) -> bool:
        """Check if a function name is available for execution."""
        return func_name in self._available_tools

    def execute(self, func_name: str, arguments: dict[str, Any] | None = None) -> dict[str, Any]:
        """Execute a target function with given arguments.

        Parameters
        ----------
        func_name : str
            Name of the tool/function to execute (e.g. 'mouse_click', 'open_app').
        arguments : dict[str, Any] | None
            Dictionary of keyword arguments to pass to the function.

        Returns
        -------
        dict[str, Any]
            Execution report containing success status, return values, or errors.
        """
        args = dict(arguments or {})

        if not func_name:
            return {
                "success": False,
                "function": None,
                "error": "No function name provided",
            }

        if func_name not in self._available_tools:
            log.error("Function '%s' is not an available tool in tools.tools", func_name)
            return {
                "success": False,
                "function": func_name,
                "arguments": args,
                "error": f"Function '{func_name}' is not an available tool",
            }

        fn = self._available_tools[func_name]

        # Dry run mode
        if self.dry_run:
            log.info("[DRY RUN] Would execute %s(**%s)", func_name, args)
            return {
                "success": True,
                "function": func_name,
                "arguments": args,
                "dry_run": True,
                "message": f"[DRY RUN] Would execute {func_name} with arguments {args}",
            }

        # Filter arguments to match target function signature
        try:
            sig = inspect.signature(fn)
            has_varkw = any(
                p.kind == inspect.Parameter.VAR_KEYWORD
                for p in sig.parameters.values()
            )
            if not has_varkw:
                valid_params = set(sig.parameters.keys())
                filtered_args = {k: v for k, v in args.items() if k in valid_params}
            else:
                filtered_args = args
        except Exception as exc:
            log.debug("Could not inspect signature of %s: %s", fn, exc)
            filtered_args = args

        log.info("Executing %s(**%s)", func_name, filtered_args)

        try:
            result = fn(**filtered_args)
            return {
                "success": True,
                "function": func_name,
                "arguments": filtered_args,
                "result": result,
            }
        except Exception as exc:
            log.exception("Execution error in %s: %s", func_name, exc)
            return {
                "success": False,
                "function": func_name,
                "arguments": filtered_args,
                "error": str(exc),
            }


def execute_action(
    func_name: str,
    arguments: dict[str, Any] | None = None,
    dry_run: bool = False,
) -> dict[str, Any]:
    """Convenience helper to execute a single action."""
    executor = ActionExecutor(dry_run=dry_run)
    return executor.execute(func_name, arguments)
